var config = $("Config").first().json;
var apifyToken = config.APIFY_API_TOKEN || '';
var BATCH_SIZE = 10;

var ghlHeaders = {
  'Authorization': 'Bearer REPLACE_WITH_GHL_API_TOKEN',
  'Content-Type': 'application/json',
  'Version': '2021-07-28'
};
var locationId = 'KM3KkAQFgG3bByTZmWLL';
var today = new Date().toISOString().split('T')[0];

var allContacts = [];
try {
  var res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://services.leadconnectorhq.com/contacts/search',
    headers: ghlHeaders,
    body: JSON.stringify({
      locationId: locationId,
      pageLimit: 100,
      filters: [{ field: 'tags', operator: 'contains', value: 'ig-comment-1' }]
    })
  });
  allContacts = res.contacts || [];
} catch (e) {
  return [{ json: { status: 'GHL error: ' + e.message, toEngageContacts: [], datasetId: '', scraperRunId: '', runDate: today } }];
}

var toEngage = [];
for (var i = 0; i < allContacts.length; i++) {
  var c = allContacts[i];
  var tags = c.tags || [];
  var alreadyDone = false;
  for (var t = 0; t < tags.length; t++) {
    if (tags[t] === 'ig-comment-2') { alreadyDone = true; }
  }
  if (alreadyDone) { continue; }
  var website = c.website || '';
  var match = website.match(/instagram\.com\/([a-zA-Z0-9._]+)/);
  if (!match) { continue; }
  toEngage.push({
    contactId: c.id,
    name: c.firstName || c.lastName || '',
    username: match[1],
    tags: tags
  });
  if (toEngage.length >= BATCH_SIZE) { break; }
}

if (toEngage.length === 0) {
  return [{ json: { status: 'No contacts ready for comment round 2 today', toEngageContacts: [], datasetId: '', scraperRunId: '', runDate: today } }];
}

var profileUrls = [];
for (var j = 0; j < toEngage.length; j++) {
  profileUrls.push('https://www.instagram.com/' + toEngage[j].username + '/');
}

var datasetId = '';
var scraperRunId = '';
var scrapeError = '';
try {
  var scrapeRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/apify~instagram-scraper/runs?token=' + apifyToken,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      directUrls: profileUrls,
      resultsType: 'posts',
      resultsLimit: 3,
      addParentData: false
    })
  });
  var scrapeData = scrapeRes.data || scrapeRes;
  datasetId = scrapeData.defaultDatasetId || '';
  scraperRunId = scrapeData.id || '';
} catch (e) {
  scrapeError = e.message || String(e);
}

return [{ json: {
  status: scrapeError ? ('Scraper error: ' + scrapeError) : 'Scraper started - waiting for post data',
  toEngageContacts: toEngage,
  datasetId: datasetId,
  scraperRunId: scraperRunId,
  runDate: today
} }];

var config = $("Config").first().json;
var apifyToken = config.APIFY_API_TOKEN || '';
var openaiKey = config.OPENAI_API_KEY || '';
var igCookiesRaw = config.IG_COOKIES || '[]';
var igCookies = (typeof igCookiesRaw === 'string') ? JSON.parse(igCookiesRaw) : igCookiesRaw;

var datasetId = $json.datasetId || '';
var toEngageContacts = $json.toEngageContacts || [];
var runDate = $json.runDate || new Date().toISOString().split('T')[0];
var scraperRunId = $json.scraperRunId || '';
var commentRunIds = [];

var ghlHeaders = {
  'Authorization': 'Bearer REPLACE_WITH_GHL_API_TOKEN',
  'Content-Type': 'application/json',
  'Version': '2021-07-28'
};

var FALLBACK_COMMENTS = [
  'That programming looks legitimately solid',
  'Your clients are lucky honestly',
  'Clean technique on that one',
  'This is the kind of training I want to try',
  'Good to see real work posted'
];

if (toEngageContacts.length === 0) {
  return [{ json: { engageSummary: $json.status || 'No contacts', engageCount: 0, engagedAccounts: 'None', runDate: runDate, costUsd: 0, scraperRunId: scraperRunId, commentRunCount: 0 } }];
}

var posts = [];
if (datasetId) {
  try {
    var dataRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/datasets/' + datasetId + '/items?token=' + apifyToken + '&limit=100'
    });
    posts = Array.isArray(dataRes) ? dataRes : [];
  } catch (e) {}
}

var postByUsername = {};
for (var i = 0; i < posts.length; i++) {
  var post = posts[i];
  var uname = post.ownerUsername || '';
  if (!uname || postByUsername[uname]) { continue; }
  var shortCode = post.shortCode || '';
  if (shortCode) {
    postByUsername[uname] = {
      url: 'https://www.instagram.com/p/' + shortCode + '/',
      caption: (post.caption || '').substring(0, 400),
      hashtags: (post.hashtags || []).slice(0, 5).join(' ')
    };
  }
}

if (Object.keys(postByUsername).length === 0) {
  return [{ json: { engageSummary: 'No post URLs found - scraper may need more time', engageCount: 0, engagedAccounts: 'None', runDate: runDate, costUsd: 0, scraperRunId: scraperRunId, commentRunCount: 0 } }];
}

var engagedLines = [];
var engageCount = 0;

for (var j = 0; j < toEngageContacts.length; j++) {
  var contact = toEngageContacts[j];
  var postData = postByUsername[contact.username] || null;
  if (!postData) { continue; }

  var aiComment = '';
  var captionContext = postData.caption || postData.hashtags || '';

  if (captionContext && openaiKey) {
    var systemPrompt = 'You write short Instagram comments that sound like a real Australian person casually scrolling their feed. Never sound like a brand, marketer, or AI. No corporate language. No hollow compliments. Tone: direct, genuine, occasionally dry - like a real person talking to a fellow PT. Rules: Max 10 words. 1 sentence only. NEVER use these words: inspiring, amazing, love this, so good, crushing it, killing it, goals, wow, incredible, phenomenal. No hashtags. No @ mentions. No selling. No brand mentions. Max 1 emoji and only if it fits naturally - do not force it. Vary the opening every single time. Never start with Love or Great or Amazing or This. Sound like you are reacting to what you actually saw in the post not just complimenting their existence. Output ONLY the comment text with no quotes around it.';
    var userPrompt = 'Post caption: ' + captionContext + '\n\nWrite one short comment reacting to this specific post.';

    try {
      var aiRes = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.openai.com/v1/chat/completions',
        headers: {
          'Authorization': 'Bearer ' + openaiKey,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          temperature: 0.9,
          max_tokens: 60
        })
      });
      aiComment = (aiRes.choices[0].message.content || '').trim();
    } catch (e) {
      aiComment = '';
    }
  }

  if (!aiComment) {
    aiComment = FALLBACK_COMMENTS[j % FALLBACK_COMMENTS.length];
  }

  var commentStarted = false;
  try {
    var commentRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.apify.com/v2/acts/mikolabs~ig-post-reel-comment-bot/runs?token=' + apifyToken,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        postUrls: [{ url: postData.url }],
        commentMessage: aiComment,
        cookies: igCookies
      })
    });
    commentStarted = true;
    engageCount++;
    engagedLines.push('@' + contact.username + ': "' + aiComment + '"');
    var commentRunData = commentRes.data || commentRes;
    if (commentRunData.id) { commentRunIds.push(commentRunData.id); }
  } catch (e) {
    engagedLines.push('@' + contact.username + ': FAILED - ' + (e.message || String(e)));
  }

  if (commentStarted) {
    var newTags = [];
    for (var q = 0; q < contact.tags.length; q++) {
      newTags.push(contact.tags[q]);
    }
    newTags.push('ig-comment-2');
    newTags.push('comment-2-date:' + runDate);
    try {
      await this.helpers.httpRequest({
        method: 'PUT',
        url: 'https://services.leadconnectorhq.com/contacts/' + contact.contactId,
        headers: ghlHeaders,
        body: JSON.stringify({ tags: newTags })
      });
    } catch (e) {}
  }
}

var totalCostUsd = 0;
var runIdsToCheck = [];
if (scraperRunId) { runIdsToCheck.push(scraperRunId); }
for (var ri = 0; ri < commentRunIds.length; ri++) { runIdsToCheck.push(commentRunIds[ri]); }
for (var ci = 0; ci < runIdsToCheck.length; ci++) {
  try {
    var costRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/actor-runs/' + runIdsToCheck[ci] + '?token=' + apifyToken
    });
    var costData = costRes.data || costRes;
    totalCostUsd += costData.usageTotalUsd || 0;
  } catch (e) {}
}

return [{ json: {
  engageSummary: 'Comment Round 2 completed',
  engageCount: engageCount,
  engagedAccounts: engagedLines.join('\n'),
  runDate: runDate,
  costUsd: totalCostUsd,
  scraperRunId: scraperRunId,
  commentRunCount: commentRunIds.length
} }];

var prev = $input.first().json;
return [{ json: {
  'Date': prev.runDate || '',
  'Workflow': 'Phase 2D - Comment Round 2',
  'Actor': 'scraper + comment-bot (' + (prev.commentRunCount || 0) + ' comments)',
  'Run ID': prev.scraperRunId || '',
  'Actions Attempted': prev.engageCount || 0,
  'Actions Succeeded': prev.engageCount || 0,
  'Cost USD': prev.costUsd || 0,
  'Status': prev.engageSummary || ''
} }];
